css:
:scope{display:block;width:100%}.pw{--bg:#0F0E0C;--tx:#EDE6D8;--lb:#C2B8A6;--rl:#8E4A30;--hl:#3A3531;background:var(--bg);color:var(--tx);font-family:var(--os-font-body);font-weight:400}.pw[data-ground="bone"]{--bg:#EDE6D8;--tx:#0F0E0C;--lb:#3A3531;--rl:#8E4A30;--hl:#3A3531}.pw[data-ground="umber"]{--bg:#3A3531;--rl:#C2B8A6;--hl:#C2B8A6}.pw[data-ground="oxblood"]{--bg:#4A1C18;--rl:#C2B8A6;--hl:#C2B8A6}.pw[data-ground="clay"]{--bg:#8E4A30;--lb:#EDE6D8;--rl:#EDE6D8;--hl:#EDE6D8}.pw[data-ground="olive"]{--bg:#3C402F;--rl:#C2B8A6;--hl:#C2B8A6}
.pw__in{box-sizing:content-box;max-width:1000px;margin:0 auto;padding:112px 32px}
.pw__kicker{margin:0;font-family:var(--os-font-label);font-weight:400;font-size:12px;letter-spacing:.3em;text-transform:uppercase;color:var(--lb)}
.pw__rule{width:64px;height:2px;background:var(--rl);margin:28px 0 32px}
.pw__in>.pw__rule:first-child{margin-top:0}
.pw__h2{margin:0;font-family:var(--os-font-heading);font-weight:500;font-size:60px;line-height:1.08;color:var(--tx);text-wrap:balance}
.pw__intro{margin:24px 0 0;font-size:21px;line-height:1.5}
.pw__ol{margin:48px 0 0;padding:0;list-style:none;display:flex;flex-direction:column;counter-reset:m}
.pw__ol li{counter-increment:m;display:flex;gap:28px;align-items:baseline;border-top:1px solid var(--hl);padding:22px 0}
.pw__ol li:last-child{border-bottom:1px solid var(--hl)}
.pw__n::before{content:counter(m,decimal-leading-zero);font-family:var(--os-font-label);font-size:12px;letter-spacing:.2em;color:var(--lb)}
.pw__t{font-family:var(--os-font-heading);font-weight:500;font-size:32px;line-height:1.2}
.pw__close{margin:40px 0 0;font-family:var(--os-font-heading);font-style:italic;font-weight:500;font-size:30px;line-height:normal}
@media (max-width:767px){.pw__in{padding:56px 20px}.pw__kicker{font-size:11px}.pw__rule{width:48px;margin:24px 0}.pw__h2{font-size:40px;line-height:1.1}.pw__intro{font-size:19px;margin-top:20px}.pw__ol{margin-top:32px}.pw__ol li{gap:18px;padding:18px 0}.pw__t{font-size:25px}.pw__close{font-size:27px;margin-top:32px}}
